/// <summary>
/// class <c>AVAItemSetInventTransferLineExplodeBOM</c>
/// </summary>
class AVABackOrderReleaseHandling
{
    public Args                             clsArgs;

    public boolean                          clsReleaseFunctionReleaseAll;           // 1 - ApprovalReleaseAll           - "Komplettfreigabe" mark possible and process marked in tmp table
    public boolean                          clsReleaseFunctionReleaseAllPossible;

    public boolean                          clsApprovalMarkAvailable;               // 2 - ApprovalMarkAvailable        - AVAStockAvailability::Available           - green, mark all
                                                                                    //                                  - AVAStockAvailability::IndividualRequired  - blue, mark all
    public boolean                          clsApprovalMarkAvailablePossible;

    public boolean                          clsReleaseFunctionReleaseMarked;        // 3 - ApprovalReleaseMarked        - "Teilfreigabe"process marked in tmp table
    public boolean                          clsReleaseFunctionReleaseMarkedPossible;

    public boolean                          clsReleasePosition;                     // 4 - ApprovalReleasePosition      - "Positionsfreigabe" process single selected

    public boolean                          clsApprovalReserveSelected;             // 5 - ApprovalReserveSelected      - Selected in Grid

    public boolean                          clsApprovalUnmarkUnreserveSelected;     // 6 - ApprovalUnreserveSelected    - Selected in Grid

    public boolean                          clsApprovalSaveOpenChanges;             // 7 - save open changes
    public boolean                          clsApprovalSaveOpenChangesPossible;

    public boolean                          clsReleaseFunctionsShippingDate;
    public boolean                          clsReleaseFunctionsReservations;
    public boolean                          clsReleaseFunctionsReservationsPossible;


    public AVAStockAvailability             clsAVAStockAvailabilityCurrent;
    public KCS_SOCPickingReleaseIndicator   clsReleaseIndicatorCurrent;
    public KCS_SOCPickingReleaseIndicator   clsReleaseIndicatorCurrentTmp;
    public SalesLine                        clsSalesLineCurrent;
    public AVASalesLineBackOrderTmp         clsSalesLineCurrentTmp;
    public InventTransferLine               clsInventTransferLineCurrent;
    public AVAInventTransferLineBackOrderTmp clsInventTransferLineCurrentTmp;

}

