/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    this.resetAllFlags();
}

/// <summary>
///     AVA <c>resetAllFlags</c> method.
/// </summary>
public void resetAllFlags()
{
    this.resetCommonFlags();
    this.resetApprovalFlags();
    this.resetReleaseFunctionsFlags();
}

 /// <summary>
 ///     AVA <c>resetCommonFlags</c> method.
 /// </summary>
public void resetCommonFlags()
{
    clsAVAStockAvailabilityCurrent   = AVAStockAvailability::Unknown;
    clsSalesLineCurrent              = null;
    clsInventTransferLineCurrent     = null;
}

/// <summary>
///      AVA <c>resetApprovalFlags</c> method.
/// </summary>
public void resetApprovalFlags()
{
     clsApprovalMarkAvailable                = false;    // "Verfügbare markieren" - Grün markieren
     clsApprovalMarkAvailablePossible        = false;    
     clsApprovalUnmarkUnreserveSelected      = false;    // "Aufheben"
     clsApprovalReserveSelected              = false;    // "Reservieren"
     clsApprovalSaveOpenChanges              = false;    // "Änderungen speichern"
     clsApprovalSaveOpenChangesPossible      = false;   
 }

/// <summary>
///    AVA <c>resetReleaseFunctionsFlags</c> method.
/// </summary>
public void resetReleaseFunctionsFlags()
{
    clsReleasePosition                      = false;    // "Positionsfreigabe"
    clsReleaseFunctionReleaseAll            = false;    // "Komplettfreigabe"
    clsReleaseFunctionReleaseAllPossible    = false;    
    clsReleaseFunctionReleaseMarked         = false;    // "Teilfreigabe"
    clsReleaseFunctionReleaseMarkedPossible = false;
    clsReleaseFunctionsShippingDate         = false;
    clsReleaseFunctionsReservations         = false;
    clsReleaseFunctionsReservationsPossible = false;
}

/// <summary>
///    AVA <c>initProcessingFlags</c> method.
/// </summary>
public void initProcessingFlags()
{
    if(clsReleasePosition)                          // "Positionsfreigabe"
    {
        clsReleaseFunctionReleaseMarked     = true; // "Teilfreigabe"
    }

    if(clsReleaseFunctionReleaseAll)                // "Komplettfreigabe"
    {
        clsApprovalMarkAvailable            = true; // "Verfügbare markieren" - Grün markieren
        clsReleaseFunctionReleaseMarked     = true; // "Teilfreigabe"
    }

    if(clsReleaseFunctionReleaseMarked)             // "Teilfreigabe"
    {
        clsReleaseFunctionsShippingDate     = true; // "Freigabefunktionen - Versanddatum"
        clsReleaseFunctionsReservations     = true; // "Freigabefunktionen - Reservierungen"
    }
}

/// <summary>
///    AVA <c>initApprovalMarkAvailable</c> method.
/// </summary>
public void initApprovalMarkAvailable()
{
    this.resetAllFlags();
    clsApprovalMarkAvailable = true; // "Verfügbare markieren" - Grün markieren
    this.initProcessingFlags();
}

