}

/// <summary>
///    AVA <c>currentSetValuesTables</c> method.
/// </summary>
/// <param name="_common">
///     <c>Common</c> as type
/// </param>
/// <param name="_commonTmp">
///     <c>Common</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentSetValuesTables(  Common  _common, 
                                        Common  _commonTmp)
{
    boolean retVal;

    if(_common.TableId == tableNum(SalesLine) && _commonTmp.TableId == tableNum(AVASalesLineBackOrderTmp))
    {
        clsSalesLineCurrent             = _common;
        clsSalesLineCurrentTmp          = _commonTmp;
        clsAVAStockAvailabilityCurrent  = clsSalesLineCurrent.avaGetStockAvailablity();
        clsReleaseIndicatorCurrent      = clsSalesLineCurrent.KCS_SOCPickingReleaseIndicator;
        clsReleaseIndicatorCurrentTmp   = clsSalesLineCurrentTmp.KCS_SOCPickingReleaseIndicator;
        retVal = true;
    }
    else if(_common.TableId == tableNum(InventTransferLine) && _commonTmp.TableId == tableNum(AVAInventTransferLineBackOrderTmp))
    {
        clsInventTransferLineCurrent    = _common;
        clsInventTransferLineCurrentTmp = _commonTmp;
        clsAVAStockAvailabilityCurrent  = clsInventTransferLineCurrent.avaGetStockAvailablity();
        clsReleaseIndicatorCurrent      = clsInventTransferLineCurrent.KCS_SOCPickingReleaseIndicator;
        clsReleaseIndicatorCurrentTmp   = clsInventTransferLineCurrentTmp.KCS_SOCPickingReleaseIndicator;
        retVal = true;
    }
    return retVal;
}

/// <summary>
///    AVA <c>currentIsAvailableOrIndividual</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentIsAvailableOrIndividual()
{
    return(     clsAVAStockAvailabilityCurrent == AVAStockAvailability::Available
            ||  clsAVAStockAvailabilityCurrent == AVAStockAvailability::IndividualRequired  );
}

/// <summary>
///    AVA <c>currentIsNotAvailableOrIndividual</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentIsNotAvailableOrIndividual()
{
    return(     !(clsAVAStockAvailabilityCurrent == AVAStockAvailability::Available)
            &&  !(clsAVAStockAvailabilityCurrent == AVAStockAvailability::IndividualRequired));
}

/// <summary>
///    AVA <c>currentReleaseIndicatorBothNo</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentReleaseIndicatorBothNo()
{
    return(     clsReleaseIndicatorCurrent      == NoYes::No
            &&  clsReleaseIndicatorCurrentTmp   == NoYes::No);
}

/// <summary>
///    AVA <c>currentReleaseIndicatorBothYes</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentReleaseIndicatorBothYes()
{
    return(     clsReleaseIndicatorCurrent      == NoYes::Yes
            &&  clsReleaseIndicatorCurrentTmp   == NoYes::Yes);
}

/// <summary>
///    AVA <c>currentReleaseIndicatorNo2Yes</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentReleaseIndicatorNo2Yes()
{
    return(     clsReleaseIndicatorCurrent      == NoYes::No
            &&  clsReleaseIndicatorCurrentTmp   == NoYes::Yes);
}

/// <summary>
///    AVA <c>currentReleaseIndicatorYes2No</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentReleaseIndicatorYes2No()
{
    return(     clsReleaseIndicatorCurrent      == NoYes::Yes
            &&  clsReleaseIndicatorCurrentTmp   == NoYes::No);
}

/// <summary>
///    AVA <c>currentReleaseIndicatorDifferent</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean currentReleaseIndicatorDifferent()
{
    return(clsReleaseIndicatorCurrent != clsReleaseIndicatorCurrentTmp);
}
